//! Solidity verifier for bleh.xyz block commitments.
//!
//! `sol/BlehBlockVerifier.sol` holds the
//! `BlehCommitments` library and the stateless `BlehBlockVerifier` test
//! contract. They verify, with `ecrecover`, exactly what the origin signs
//! (`mesh_types::signing` and `mesh_types::merkle`): a block commitment's
//! EIP-191 secp256k1 signature, and RFC 9162 inclusion proofs of canonical
//! record bytes under its Merkle root.
//!
//! This crate carries the compiled bytecode, generated by `compile.mjs` with
//! the pinned compiler (see `README.md`). Its tests deploy the bytecode in an
//! in-process EVM (`revm`) and check it against commitments and proofs
//! produced by the bus signer with a test key.

#[rustfmt::skip]
mod bytecode;

pub use bytecode::{
    CREATION_CODE, METHOD_IDS, RUNTIME_CODE, SOLC_SETTINGS, SOLC_VERSION, SOURCE_SHA256,
};

/// The Solidity source the bytecode was compiled from.
pub const SOURCE: &str = include_str!("../sol/BlehBlockVerifier.sol");

/// Decodes lowercase or uppercase hex without a `0x` prefix.
#[must_use]
pub fn decode_hex(s: &str) -> Option<Vec<u8>> {
    fn nibble(c: u8) -> Option<u8> {
        match c {
            b'0'..=b'9' => Some(c - b'0'),
            b'a'..=b'f' => Some(c - b'a' + 10),
            b'A'..=b'F' => Some(c - b'A' + 10),
            _ => None,
        }
    }
    let (pairs, rest) = s.as_bytes().as_chunks::<2>();
    if !rest.is_empty() {
        return None;
    }
    pairs
        .iter()
        .map(|&[hi, lo]| Some((nibble(hi)? << 4) | nibble(lo)?))
        .collect()
}

/// The 4-byte selector of a function, by its canonical signature (for
/// example `leafHash(bytes)`), as reported by the compiler.
#[must_use]
pub fn selector(signature: &str) -> Option<[u8; 4]> {
    let (_, hex) = METHOD_IDS.iter().find(|(s, _)| *s == signature)?;
    decode_hex(hex)?.try_into().ok()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn hex_decodes() {
        assert_eq!(decode_hex("00ff10Ab"), Some(vec![0, 255, 16, 171]));
        assert_eq!(decode_hex("0"), None);
        assert_eq!(decode_hex("zz"), None);
        assert!(decode_hex(CREATION_CODE).is_some());
        assert!(decode_hex(RUNTIME_CODE).is_some());
    }

    #[test]
    fn selectors_are_listed() {
        assert!(selector("leafHash(bytes)").is_some());
        assert!(selector("nope()").is_none());
    }
}
